static int l_city_index(lua_State *L)
{
    city *p = api_check_city(L, 1);
    lua_pushvalue(L, 2);
    lua_rawget(L, lua_upvalueindex(1));
    if (!lua_isnil(L, -1)) return 1;
    lua_pop(L, 1);
    const char *k = lua_tostring(L, 2);
    if (!k) return 0;
    if (!strcmp(k, "ground")) { api_push_texture(L, p->ground); return 1; }
    if (!strcmp(k, "defs")) {
        lua_createtable(L, p->def_count, 0);
        for (int i = 0; i < p->def_count; i++) { api_push_building_def(L, p->defs[i]); lua_rawseti(L, -2, i + 1); }
        return 1;
    }
    if (!strcmp(k, "items")) {
        lua_createtable(L, p->count, 0);
        for (int i = 0; i < p->count; i++) { api_push_building(L, p->items[i]); lua_rawseti(L, -2, i + 1); }
        return 1;
    }
    if (!strcmp(k, "count")) { lua_pushinteger(L, p->count); return 1; }
    if (!strcmp(k, "zones")) {
        lua_createtable(L, p->zone_count, 0);
        for (int i = 0; i < p->zone_count; i++) { api_push_city_zone(L, p->zones[i]); lua_rawseti(L, -2, i + 1); }
        return 1;
    }
    if (!strcmp(k, "zone_count")) { lua_pushinteger(L, p->zone_count); return 1; }
    if (!strcmp(k, "open")) { lua_pushinteger(L, (lua_Integer)p->open); return 1; }
    if (!strcmp(k, "spacing")) { lua_pushnumber(L, p->spacing); return 1; }
    if (!strcmp(k, "tile")) { api_push_size2(L, p->tile); return 1; }
    if (!strcmp(k, "clearance")) { api_push_size2(L, p->clearance); return 1; }
    if (!strcmp(k, "buildable")) { lua_getiuservalue(L, 1, 1); lua_getfield(L, -1, "buildable"); return 1; }
    if (!strcmp(k, "zone_at")) { lua_getiuservalue(L, 1, 1); lua_getfield(L, -1, "zone_at"); return 1; }
    if (!strcmp(k, "zone_touches")) { lua_getiuservalue(L, 1, 1); lua_getfield(L, -1, "zone_touches"); return 1; }
    if (!strcmp(k, "draw_over")) { lua_getiuservalue(L, 1, 1); lua_getfield(L, -1, "draw_over"); return 1; }
    if (!strcmp(k, "cam")) { api_push_camera(L, p->cam); return 1; }
    if (!strcmp(k, "fog")) { api_push_color(L, p->fog); return 1; }
    if (!strcmp(k, "fog_on_land_only")) { lua_pushboolean(L, p->fog_on_land_only); return 1; }
    if (!strcmp(k, "path")) { api_push_color(L, p->path); return 1; }
    if (!strcmp(k, "movable")) { lua_pushboolean(L, p->movable); return 1; }
    if (!strcmp(k, "show_footprints")) { lua_pushboolean(L, p->show_footprints); return 1; }
    if (!strcmp(k, "income_icon")) { api_push_texture(L, p->income_icon); return 1; }
    if (!strcmp(k, "selected")) { lua_pushinteger(L, p->selected); return 1; }
    if (!strcmp(k, "placing")) { lua_pushinteger(L, p->placing); return 1; }
    if (!strcmp(k, "moving")) { lua_pushinteger(L, p->moving); return 1; }
    if (!strcmp(k, "ghost")) { api_push_vec2(L, p->ghost); return 1; }
    if (!strcmp(k, "held")) { lua_pushboolean(L, p->held); return 1; }
    return luaL_error(L, "city has no field '%s'", k);
}

static int l_city_newindex(lua_State *L)
{
    city *p = api_check_city(L, 1);
    const char *k = lua_tostring(L, 2);
    if (!k) return luaL_error(L, "city: bad field");
    if (!strcmp(k, "defs")) {
        luaL_checktype(L, 3, LUA_TTABLE);
        int n = (int)luaL_len(L, 3);
        free(p->defs);
        p->defs = calloc((size_t)(n > 0 ? n : 1), sizeof *p->defs);
        for (int i = 0; i < n; i++) { lua_rawgeti(L, 3, i + 1); p->defs[i] = api_get_building_def(L, -1); lua_pop(L, 1); }
        p->def_count = n;
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "defs"); lua_pop(L, 1);
        return 0;
    }
    if (!strcmp(k, "items")) {
        luaL_checktype(L, 3, LUA_TTABLE);
        int n = (int)luaL_len(L, 3);
        luaL_argcheck(L, n <= CITY_MAX, 3, "too many");
        for (int i = 0; i < n; i++) { lua_rawgeti(L, 3, i + 1); p->items[i] = api_get_building(L, -1); lua_pop(L, 1); }
        p->count = n;
        return 0;
    }
    if (!strcmp(k, "count")) { p->count = (int)lua_tonumber(L, 3); return 0; }
    if (!strcmp(k, "zones")) {
        luaL_checktype(L, 3, LUA_TTABLE);
        int n = (int)luaL_len(L, 3);
        luaL_argcheck(L, n <= CITY_ZONES, 3, "too many");
        for (int i = 0; i < n; i++) { lua_rawgeti(L, 3, i + 1); p->zones[i] = api_get_city_zone(L, -1); lua_pop(L, 1); }
        p->zone_count = n;
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "zones"); lua_pop(L, 1);
        return 0;
    }
    if (!strcmp(k, "open")) { p->open = (unsigned)lua_tonumber(L, 3); return 0; }
    if (!strcmp(k, "spacing")) { p->spacing = (float)lua_tonumber(L, 3); return 0; }
    if (!strcmp(k, "tile")) { p->tile = api_get_size2(L, 3); return 0; }
    if (!strcmp(k, "clearance")) { p->clearance = api_get_size2(L, 3); return 0; }
    if (!strcmp(k, "buildable")) {
        if (!lua_isnoneornil(L, 3)) luaL_checktype(L, 3, LUA_TFUNCTION);
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "buildable"); lua_pop(L, 1);
        p->buildable = lua_isnoneornil(L, 3) ? NULL : lcity_buildable;
        return 0;
    }
    if (!strcmp(k, "zone_at")) {
        if (!lua_isnoneornil(L, 3)) luaL_checktype(L, 3, LUA_TFUNCTION);
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "zone_at"); lua_pop(L, 1);
        p->zone_at = lua_isnoneornil(L, 3) ? NULL : lcity_zone_at;
        return 0;
    }
    if (!strcmp(k, "zone_touches")) {
        if (!lua_isnoneornil(L, 3)) luaL_checktype(L, 3, LUA_TFUNCTION);
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "zone_touches"); lua_pop(L, 1);
        p->zone_touches = lua_isnoneornil(L, 3) ? NULL : lcity_zone_touches;
        return 0;
    }
    if (!strcmp(k, "draw_over")) {
        if (!lua_isnoneornil(L, 3)) luaL_checktype(L, 3, LUA_TFUNCTION);
        lua_getiuservalue(L, 1, 1); lua_pushvalue(L, 3); lua_setfield(L, -2, "draw_over"); lua_pop(L, 1);
        p->draw_over = lua_isnoneornil(L, 3) ? NULL : lcity_draw_over;
        return 0;
    }
    if (!strcmp(k, "cam")) { p->cam = api_get_camera(L, 3); return 0; }
    if (!strcmp(k, "fog")) { p->fog = api_get_color(L, 3); return 0; }
    if (!strcmp(k, "fog_on_land_only")) { p->fog_on_land_only = lua_toboolean(L, 3); return 0; }
    if (!strcmp(k, "path")) { p->path = api_get_color(L, 3); return 0; }
    if (!strcmp(k, "movable")) { p->movable = lua_toboolean(L, 3); return 0; }
    if (!strcmp(k, "show_footprints")) { p->show_footprints = lua_toboolean(L, 3); return 0; }
    if (!strcmp(k, "income_icon")) { p->income_icon = api_get_texture(L, 3); return 0; }
    if (!strcmp(k, "selected")) { p->selected = (int)lua_tonumber(L, 3); return 0; }
    if (!strcmp(k, "ghost")) { p->ghost = api_get_vec2(L, 3); return 0; }
    if (!strcmp(k, "held")) { p->held = lua_toboolean(L, 3); return 0; }
    return luaL_error(L, "city: cannot set field '%s'", k);
}

