/* app.mesh(pts, colors, indices) */
static int l_app_renderer_geometry(lua_State *L)
{
    vec2 a_pts[API_MAX_ARRAY];
    int n_pts = api_array_len(L, 1, API_MAX_ARRAY);
    for (int k = 0; k < n_pts; k++) { lua_rawgeti(L, 1, k + 1); a_pts[k] = api_get_vec2(L, -1); lua_pop(L, 1); }
    color a_colors[API_MAX_ARRAY];
    int n_colors = api_array_len(L, 2, API_MAX_ARRAY);
    for (int k = 0; k < n_colors; k++) { lua_rawgeti(L, 2, k + 1); a_colors[k] = api_get_color(L, -1); lua_pop(L, 1); }
    int a_indices[API_MAX_ARRAY];
    int n_indices = api_array_len(L, 3, API_MAX_ARRAY);
    for (int k = 0; k < n_indices; k++) { lua_rawgeti(L, 3, k + 1); a_indices[k] = (int)lua_tonumber(L, -1); lua_pop(L, 1); }
    draw_mesh(a_pts, a_colors, n_pts, a_indices, n_indices);
    return 0;
}

